import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  label?: string;
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  defaultTags = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const apply = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const add = (next: string[]) => {
    const unique: string[] = [];
    for (const tag of next) {
      const trimmed = tag.trim();
      if (trimmed && !unique.includes(trimmed)) unique.push(trimmed);
    }
    apply(unique);
  };

  const remove = (tag: string) => {
    apply(tags.filter((item) => item !== tag));
  };

  return (
    <div style={{ display: 'grid', gap: '12px' }}>
      <div style={{ display: 'grid', gap: '6px' }}>
        <span
          className="jx-label"
          style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)' }}
        >
          {label}
        </span>
        <JxTagInput
          ariaLabel={label}
          placeholder="Введите тег и нажмите Enter"
          value={tags}
          onValueChange={add}
        />
        <span
          className="jx-input-help"
          style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-sans)' }}
        >
          Enter добавляет тег, Backspace удаляет последний
        </span>
      </div>

      {tags.length === 0 ? (
        <JxEmptyState
          title="Тегов пока нет"
          message="Добавьте хотя бы один тег, чтобы статью было проще найти."
        />
      ) : (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: '8px',
            padding: '12px',
            background: 'var(--jx-surface-2)',
            border: '1px solid var(--jx-border)',
            borderRadius: 'var(--jx-r)',
          }}
        >
          {tags.map((tag) => (
            <span key={tag} role="listitem">
              <JxChip active removable onRemove={() => remove(tag)}>
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

